// OpenTPU: an open-source re-implementation of Google's Tensor Processing Unit by the UC Santa Barbara ArchLab
// (https://github.com/UCSBarchlab/OpenTPU). Matrix multiply unit (8x8 systolic array of int8 MACs), weight FIFO,
// unified buffer, accumulators, activation unit (ReLU / sigmoid), host memory and weight DRAM interfaces, and the
// instruction decoder for RHM, WHM, RW, MMC, ACT, NOP and HLT.
//
// This file is OpenTPU's PyRTL design exported to Verilog with PyRTL 0.10.2 (pyrtl.output_to_verilog), unchanged
// apart from the module name. Export settings, see config.py of OpenTPU:
//   MATSIZE = 8, and smaller memories than the original for the browser:
//   IMEM_ADDR_SIZE = 9 (512 instructions), UB_ADDR_SIZE = 8 (256 vectors), ACC_ADDR_SIZE = 8 (256 vectors)
// The ports PyRTL leaves unnamed got the names of their Python variables (halt, hostmem_*, weights_dram_*), and the
// main registers and control signals were named for the wave window (pc, instr, dispatch_*, rhm_*, whm_*, mm_busy, ...).
// For PyRTL 0.10, helperfuncs.mult_signed in matrix.py is called signed_mult.
// Memories: mem_0 instructions, mem_1 unified buffer, mem_2..mem_9 accumulators, mem_10..mem_17 sigmoid ROMs.
//
